<template><section class="intake-follow-up"><h3>{{t('intakeTitle')}}</h3><p>{{t('unconfirmedFact')}}</p><p v-if="!items.length">{{t('noIntakes')}}</p><article v-for="row in items" :key="row.intakeId"><h4>#{{row.intakeId}} · {{t(row.status)}}</h4><p>{{row.scheduledAtUtc || t('unknownUtc')}} · {{t(row.provenance || 'PERSONAL_UNVERIFIED')}}</p><p>{{t(row.followUpState || 'OPEN')}} · {{t(row.followUpKind || 'FOLLOW_UP_ONLY')}} · {{t('cycle')}} {{row.cycle || 1}}</p><p>{{t('stockOutcome')}}: {{t(row.stockOutcome || 'UNRECONCILED')}}</p><p v-if="row.actualAt">{{t('actualUtc')}}: {{row.actualAt}}</p><IntakeFactReview :fact="row.latestFact"/><div class="intake-actions"><button v-for="operation in row.allowedCommands" :key="operation" type="button" :data-operation="operation" :disabled="disabled" @click="$emit('command',operation,row)">{{t(operation)}}</button></div></article><button v-if="nextCursor" type="button" @click="$emit('more')">{{t('more')}}</button></section></template>
